from pathlib import Path
import pandas as pd,numpy as np,json,sqlite3
from common import *
ROOT=Path(__file__).parent;OUT=ROOT/'outputs'
def plan(initial=1000,growth=.1,separation=.035,months=12,cost=4000,capacity=40):
 vals=[initial,growth,separation,months,cost,capacity]
 if not all(np.isfinite(v) for v in vals) or initial<=0 or not -.9<=growth<=1 or not 0<=separation<1 or months!=int(months) or not 1<=months<=60 or cost<0 or capacity<0:raise ValueError('Invalid planning inputs')
 target=initial*(1+growth);q=1-separation;survival=q**months;factor=months if separation==0 else (1-survival)/separation;raw=(target-initial*survival)/factor;h=max(0,raw);path=[initial];cap=[initial]
 for _ in range(int(months)):path.append(path[-1]*q+h);cap.append(cap[-1]*q+capacity)
 hires=h*months;net=path[-1]-initial
 return dict(monthly_hires=h,total_hires=hires,replacements=hires-net,achieved_headcount=path[-1],target_headcount=target,capacity_headcount=cap[-1],capacity_gap=cap[-1]-target,budget=hires*cost,path=path,capacity_path=cap,zero_hire_floor=initial*survival,target_requires_additional_separations=raw<0)
def evaluate(series):
 rows=[];values=series.to_numpy();dates=series.index
 for i in range(12,len(values)-2):
  if dates[i]<pd.Timestamp('2023-01-01'):continue
  y=float(np.mean(values[i:i+3]));forecast={'last_month':values[i-1],'mean_3':np.mean(values[i-3:i]),'mean_12':np.mean(values[i-12:i]),'seasonal_12':np.mean(values[i-12:i-9])}
  # A split belongs to the period containing the LAST target month; validation cannot see holdout months.
  split='validation' if dates[i+2]<pd.Timestamp('2025-01-01') else 'holdout'
  if split=='holdout' and dates[i]<pd.Timestamp('2025-01-01'):continue
  for method,pred in forecast.items():rows.append(dict(origin=dates[i-1],target_start=dates[i],target_end=dates[i+2],split=split,method=method,actual=y,prediction=float(pred),error=float(pred-y)))
 return pd.DataFrame(rows)
def main():
 obs=pd.read_csv(ROOT/'data/observations.csv');meta=pd.read_csv(ROOT/'data/series.csv',dtype=str).fillna('');obs['date']=pd.to_datetime(obs.year.astype(str)+'-'+obs.period.str[1:]+'-01');d=obs.merge(meta[['series_id','industry_code','dataelement_code','ratelevel_code']],on='series_id',validate='many_to_one');assert not d.duplicated(['series_id','date']).any();assert d.value.notna().all();names=json.loads((ROOT/'data/industries.json').read_text());latest=d.date.max();assert latest==pd.Timestamp('2026-08-01');checks=[]
 release=pd.read_csv(ROOT/'data/release_table_extract.csv')
 for _,r in release.iterrows():
  code=next(k for k,v in names.items() if v==r.category)
  for metric in ['JO','HI','TS']:
   for suffix,dt in [('2025_08','2025-08-01'),('2026_07','2026-07-01'),('2026_08','2026-08-01')]:
    val=d.loc[(d.industry_code==code)&(d.dataelement_code==metric)&(d.ratelevel_code==r.kind)&(d.date==pd.Timestamp(dt)),'value'].item();expected=float(r[metric+'_'+suffix]);assert abs(val-expected)<1e-8;checks.append(dict(industry=names[code],kind=r.kind,metric=metric,date=dt,bulk_value=val,release_value=expected,difference=val-expected))
 pd.DataFrame(checks).to_csv(OUT/'release_reconciliation.csv',index=False)
 summary=[];all_eval=[];models=[];data=[]
 for code,name in names.items():
  group=d[d.industry_code==code];p=group.pivot(index='date',columns=['dataelement_code','ratelevel_code'],values='value').sort_index();assert len(p)==140 and not p.isna().any().any();assert p.index.equals(pd.date_range('2015-01-01',latest,freq='MS'))
  s=p[('TS','R')];ev=evaluate(s);ev['industry']=name;all_eval.append(ev);scores=ev.groupby(['split','method']).error.agg(mae=lambda x:x.abs().mean(),bias='mean').reset_index();val=scores[scores.split=='validation'].sort_values(['mae','method']);chosen=val.iloc[0]['method'];h=scores[(scores.split=='holdout')&(scores.method==chosen)].iloc[0];base=scores[(scores.split=='holdout')&(scores.method=='last_month')].iloc[0];model=dict(industry=name,selected_on_2023_2024=chosen,holdout_mae_pp=float(h.mae),baseline_mae_pp=float(base.mae),holdout_bias_pp=float(h.bias),baseline_bias_pp=float(base.bias),comparison=('Better' if h.mae<base.mae-1e-10 else 'Worse' if h.mae>base.mae+1e-10 else 'Tied'),outperformed_baseline=bool(h.mae<base.mae-1e-10),holdout_origins=int(len(ev[(ev.split=='holdout')&(ev.method==chosen)])));models.append(model)
  last12=s.tail(12);mean=float(last12.mean()/100);r=plan(separation=mean);latest_hires=float(p[('HI','L')].iloc[-1]);latest_sep=float(p[('TS','L')].iloc[-1]);latest_open=float(p[('JO','L')].iloc[-1]);summary.append(dict(industry=name,latest_separation_pct=float(s.iloc[-1]),trailing12_mean_pct=mean*100,latest_hires_thousands=latest_hires,latest_separations_thousands=latest_sep,latest_net_flow_thousands=latest_hires-latest_sep,latest_openings_thousands=latest_open,scenario_monthly_hires=r['monthly_hires'],scenario_total_hires=r['total_hires'],scenario_replacements=r['replacements'],scenario_budget=r['budget']))
  data.append(dict(code=code,name=name,separation=mean,low=float(last12.min()/100),high=float(last12.max()/100),latest_rate=float(s.iloc[-1]/100),history=[dict(date=x.date().isoformat(),rate=float(y)) for x,y in s.items()]))
 summary=pd.DataFrame(summary);summary.to_csv(OUT/'industry_planning_inputs.csv',index=False);pd.concat(all_eval).to_csv(OUT/'forecast_origin_results.csv',index=False);pd.DataFrame(models).to_csv(OUT/'forecast_holdout_scorecard.csv',index=False)
 scenarios=[]
 for z in data:
  for rate_kind in ['low','separation','high']:
   for growth in [0,.05,.1,.2]:
    r=plan(growth=growth,separation=z[rate_kind]);scenarios.append(dict(industry=z['name'],rate_kind=rate_kind,monthly_separation_pct=z[rate_kind]*100,growth_pct=growth*100,monthly_hires=r['monthly_hires'],total_hires=r['total_hires'],replacements=r['replacements'],budget=r['budget']))
 pd.DataFrame(scenarios).to_csv(OUT/'planning_scenarios.csv',index=False)
 con=sqlite3.connect(':memory:');d[['industry_code','date','dataelement_code','ratelevel_code','value']].to_sql('observations',con,index=False);sql=pd.read_sql_query((ROOT/'reconcile.sql').read_text(),con);sql.to_csv(OUT/'sql_planning_inputs.csv',index=False)
 for _,row in sql.iterrows():assert abs(row.trailing12_mean_pct-summary.set_index('industry').loc[names[row.industry_code],'trailing12_mean_pct'])<1e-9
 fig,ax=plt.subplots(figsize=(10,5.2));g=summary[summary.industry!='Total private'].sort_values('scenario_replacements');ax.barh(g.industry,g.scenario_replacements,color='#87c5ff',label='Replacement hires');ax.barh(g.industry,[100]*len(g),left=g.scenario_replacements,color='#f8c981',label='Net headcount increase');ax.set_xlabel('Modeled hires over 12 months');ax.set_title('100 net new roles can require far more than 100 hires',loc='left',pad=42);ax.legend(loc='upper center',bbox_to_anchor=(.5,1.16),ncol=2,frameon=False);savefig(OUT,'hiring-bridge',fig)
 fig,ax=plt.subplots(figsize=(10,4.8));g=pd.DataFrame(models);x=np.arange(len(g));ax.bar(x-.18,g.holdout_mae_pp,.36,label='Validation-selected method',color='#87c5ff');ax.bar(x+.18,g.baseline_mae_pp,.36,label='Last-month baseline',color='#f8c981');ax.set_xticks(x,['Private','Construction','Manufacturing','Retail','Business\nservices','Education\n& health','Hospitality']);ax.tick_params(axis='x',labelsize=8);ax.set_ylabel('Holdout MAE (percentage points)');ax.set_title('A selected method still has to beat the simple baseline',loc='left',pad=42);ax.legend(loc='upper center',bbox_to_anchor=(.5,1.17),ncol=2,frameon=False);savefig(OUT,'forecast-scorecard',fig)
 private=summary.iloc[0];wins=sum(x['outperformed_baseline'] for x in models);finding=f"At the trailing 12-month private-sector separation-rate average of {private.trailing12_mean_pct:.2f}% per month, a hypothetical employer growing from 1,000 to 1,100 staff needs {private.scenario_total_hires:,.0f} hires, not 100. The difference is replacement demand under the stated recurrence."
 limits='National industry estimates are not firm-specific turnover probabilities. Total separations include quits, layoffs and other exits. Rates use BLS employment denominators and are rounded. The recurrence instead applies the chosen rate to beginning-month modeled staff, an explicit planning approximation. Same-month hires and exits are not modeled separately. Staffing, growth, capacity and cost inputs are hypothetical. Revised and concurrently seasonally adjusted history is not a real-time vintage backtest. Overlapping three-month targets are dependent, so no significance test or forecast interval is claimed. Latest August estimates are preliminary. Current staffing decisions need company-level evidence.'
 result=dict(observation_month='2026-08',latest_preliminary=True,industries=data,finding=finding,limitations=limits,release_checks=len(checks),forecast_methods_outperforming_baseline=wins,scorecard=models);dump(OUT/'summary.json',result)
 report='<section class="section"><h2>Growth is only part of the hiring budget.</h2><p>'+finding+'</p><div class="note">Observed evidence: seasonally adjusted U.S. JOLTS data through August 2026, retrieved October 30. Scenario: 1,000 starting staff, 10% growth, 12 months, constant monthly hiring and an industry-rate proxy. This is not an employer forecast.</div>'+figure(OUT,'hiring-bridge','Hypothetical staffing plans calibrated to the arithmetic mean of the latest 12 published monthly separation rates. Colors separate replacement hires from the assumed 100-person net increase. This is not an official annual BLS rate.')+'<h2>The business decision</h2><p>Before approving 100 additional roles, estimate the recruiting capacity needed to replace exits as well. A monthly hiring limit can prevent the headcount target from being reached even when the budget covers the nominal new positions.</p>'+table(summary[['industry','trailing12_mean_pct','scenario_total_hires','scenario_replacements','scenario_budget']])+'<h2>Does a forecast improve the input?</h2><p>Four prespecified methods predict the next three-month average separation rate: last month, trailing three months, trailing twelve months and the same three months a year earlier. Choose a method using targets ending in 2023-2024; evaluate targets beginning in 2025 through the last fully observed three-month window. No 2025 target enters selection. On the holdout, the selected method beats the last-month baseline in '+str(wins)+' of seven industry series. This small diagnostic does not justify a production forecast.</p>'+figure(OUT,'forecast-scorecard','Chronological evaluation on current revised history. Lower MAE is better. Industries include overlapping total-private coverage and are not independent trials.')+table(pd.DataFrame(models))+'<h2>Method and reconciliation</h2><p>Headcount evolves as N[t+1] = N[t] × (1 − s) + h. Constant h is solved analytically to reach the target; replacement hires equal total hires minus net headcount change. Zero-turnover and zero-hiring boundaries are explicit. SQL independently calculates trailing-rate means; '+str(len(checks))+' bulk-file observations reconcile exactly to separate release-table cells across levels, rates and three months.</p><p>Job openings are a stock at month-end; hires and separations are flows during the month. Openings are retained for context, never divided into hires to claim a vacancy-filling probability.</p><p><a href="workbench.html">Test the hiring plan</a></p><details><summary>Limitations and validation detail</summary><p>'+limits+'</p><p>Low and high cases are the observed minimum and maximum of the last 12 monthly industry rates, not confidence limits. A target below natural attrition’s zero-hire outcome requires additional separations, which this tool flags rather than assuming negative hires.</p></details><h2>Evidence</h2><p><a href="industry_planning_inputs.csv">Industry evidence</a> · <a href="forecast_origin_results.csv">Every forecast origin</a> · <a href="forecast_holdout_scorecard.csv">Holdout scorecard</a> · <a href="release_reconciliation.csv">Release reconciliation</a> · <a href="planning_scenarios.csv">Planning scenarios</a> · <a href="sql_planning_inputs.csv">SQL check</a></p><p><a href="https://www.bls.gov/news.release/jolts.tn.htm">BLS definitions and revisions</a> · <a href="https://download.bls.gov/pub/time.series/jt/">Official bulk data</a></p></section>'
 page(ROOT,'report.html','How much hiring does growth really require?',finding,report)
 options=''.join(f'<option value="{i}">{z["name"]}</option>' for i,z in enumerate(data));controls=[('initial','Starting staff',1000),('growth','Headcount target change (%)',10),('months','Months in plan',12),('cost','Assumed cost per hire ($)',4000),('capacity','Monthly hiring capacity',40)]
 form='<section class="section"><p class="note">Industry evidence through August 2026. Every company input and staffing outcome below is hypothetical. Fractional hires represent planning averages, not executable requisitions.</p><form id="scenario"><div class="formgrid"><label for="industry">Industry proxy<select id="industry">'+options+'</select></label><label for="ratecase">Rate assumption<select id="ratecase"><option value="separation">Trailing 12-month mean</option><option value="low">Lowest observed month in last 12</option><option value="high">Highest observed month in last 12</option></select></label>'+''.join(f'<label for="{i}">{label}<input id="{i}" type="number" step="any" value="{v}" required></label>' for i,label,v in controls)+'</div><button type="submit">Recalculate hiring plan</button></form><div id="results" class="results" aria-live="polite"></div><button id="download" type="button">Download scenario JSON</button><details><summary>Understand the proxy and boundaries</summary><p>'+limits+'</p><p>The required plan and capacity-limited plan assume constant monthly hiring. Budget covers required hires only, using your cost input; it excludes wages, vacancy costs and training delays. Observed min/max cases are scenarios, not probability bounds.</p></details><p><a href="report.html">Read evidence and forecast results</a></p></section>'
 page(ROOT,'workbench.html','Budget for the hires behind the headcount.', 'Test replacement demand, recruiting capacity and the growth target together.',form,(OUT/'calculator.js').read_text(),result)
 (ROOT/'docs/executive_memo.md').write_text('# Decision memo\n\n'+finding+'\n\nUse replacement demand to challenge a recruiting-capacity assumption before committing to the growth plan. Compare industry evidence with the employer’s observed exits and time to fill.\n\nThe validation-selected forecasting methods outperform the simple baseline in '+str(wins)+' of seven series. Keep this diagnostic separate from the staffing scenario and avoid treating the selected method as established production forecasting.\n\n## Limits\n'+limits+'\n');print(finding)
if __name__=='__main__':main()
